<div class="row g-3">
  <div class="col-md-3"><label class="form-label">Eyebrow</label><input class="form-control" name="eyebrow"></div>
  <div class="col-md-5"><label class="form-label">Title *</label><input class="form-control" required name="title"></div>
  <div class="col-md-4"><label class="form-label">Image (max 2MB)</label><input class="form-control" type="file" name="image" accept="image/*" data-image-input><img data-image-preview-for="image" class="d-none mt-2 rounded border" alt="Slider preview" style="width:140px;height:80px;object-fit:contain"></div>
  <div class="col-12"><label class="form-label">Description</label><textarea class="form-control" rows="3" name="description"></textarea></div>
  <div class="col-md-3"><label class="form-label">Offer label</label><input class="form-control" name="offer_label"></div>
  <div class="col-md-3"><label class="form-label">Offer text</label><input class="form-control" name="offer_text"></div>
  <div class="col-md-3"><label class="form-label">Offer note</label><input class="form-control" name="offer_note"></div>
  <div class="col-md-3"><label class="form-label">Button text</label><input class="form-control" name="button_text"></div>
  <div class="col-md-6"><label class="form-label">Button URL</label><input class="form-control" name="button_url" placeholder="/shop or https://example.com/shop"></div>
  <div class="col-md-2"><label class="form-label">Background</label><input class="form-control form-control-color" type="color" name="background_color" value="#f4f6ed"></div>
  <div class="col-md-2"><label class="form-label">Position</label><input class="form-control" type="number" min="0" name="position" value="0"></div>
  <div class="col-md-2"><label class="form-label">Status</label><select class="form-select" name="status"><option value="1">Active</option><option value="0">Inactive</option></select></div>
</div>
